from pathlib import Path
def read_export_safe(base_dir: Path, user_file: str) -> str:
    # Fix CWE-22 by resolving and validating relative containment
    resolved = (base_dir / user_file).resolve()
    if not resolved.is_relative_to(base_dir.resolve()):
        raise PermissionError('Path traversal detected')
    return resolved.read_text(encoding='utf-8')

import hmac
def verify_token_constant_time(secret_a: bytes, secret_b: bytes) -> bool:
    # Fix CWE-208 via constant-time byte comparison
    return hmac.compare_digest(secret_a, secret_b)
